// Calcula la precisión del agente a partir de los casos de prueba
// completados manualmente en el nodo "Casos de prueba".
const casos = $input.first().json.casos;

if (!Array.isArray(casos) || casos.length === 0) {
  throw new Error('No hay casos de prueba cargados. Completá el nodo "Casos de prueba".');
}

const normaliza = (t) => (t || '').toString().trim().toLowerCase();

let total = casos.length;
let aciertos = 0;

// Casos donde se espera la contingencia "No sé"
let esperaNoSe = casos.filter(c => c.tipo_esperado === 'no_se');
let detectaNoSeCorrectamente = 0;

// Casos donde se espera una respuesta con información del manual
let esperaResponde = casos.filter(c => c.tipo_esperado === 'responde');
let respondeConFuente = 0;

for (const caso of casos) {
  const respuesta = normaliza(caso.respuesta_agente);
  const empiezaConNoSe = respuesta.startsWith('no sé') || respuesta.startsWith('no se');
  const citaFuente = normaliza(caso.respuesta_agente).includes('fuente: manual de políticas comerciales');

  if (caso.tipo_esperado === 'no_se') {
    if (empiezaConNoSe) detectaNoSeCorrectamente++;
  }

  if (caso.tipo_esperado === 'responde') {
    if (citaFuente) respondeConFuente++;
  }

  // es_correcta se marca manualmente por el evaluador (revisión cualitativa
  // de si el contenido de la respuesta es correcto según el manual). Si no
  // fue completado, se infiere de forma básica con las reglas anteriores.
  const correctaInferida =
    (caso.tipo_esperado === 'no_se' && empiezaConNoSe) ||
    (caso.tipo_esperado === 'responde' && citaFuente && respuesta.length > 0);

  const esCorrecta = (caso.es_correcta === true) || correctaInferida;
  if (esCorrecta) aciertos++;
}

const precisionGeneral = total > 0 ? (aciertos / total) * 100 : 0;
const recallNoSe = esperaNoSe.length > 0
  ? (detectaNoSeCorrectamente / esperaNoSe.length) * 100
  : null;
const citacionFuente = esperaResponde.length > 0
  ? (respondeConFuente / esperaResponde.length) * 100
  : null;

return [{
  json: {
    total_casos: total,
    aciertos,
    precision_general_pct: Number(precisionGeneral.toFixed(2)),
    casos_esperan_no_se: esperaNoSe.length,
    no_se_detectado_correctamente: detectaNoSeCorrectamente,
    recall_contingencia_no_se_pct: recallNoSe !== null ? Number(recallNoSe.toFixed(2)) : null,
    casos_esperan_respuesta: esperaResponde.length,
    respuestas_con_fuente_citada: respondeConFuente,
    citacion_fuente_pct: citacionFuente !== null ? Number(citacionFuente.toFixed(2)) : null,
    detalle_casos: casos
  }
}];

// Evalúa los resultados de la búsqueda semántica previa (retrieval),
// antes de dejar pasar la consulta al LLM.
// Es robusto ante distintos formatos de salida del nodo Vector Store
// (busca el score y el contenido en varias rutas posibles).

const UMBRAL_SIMILITUD = 0.70; // ajustar según pruebas de precisión

const items = $input.all();

function extraerScore(json) {
  const candidatos = [
    json.score,
    json.similarity,
    json?.document?.metadata?.score,
    json?.metadata?.score
  ];
  for (const c of candidatos) {
    if (typeof c === 'number' && !Number.isNaN(c)) return c;
  }
  return null;
}

function extraerTexto(json) {
  return (
    json?.document?.pageContent ||
    json?.pageContent ||
    json?.text ||
    ''
  );
}

const chunksEncontrados = items.length;

let scores = items.map(i => extraerScore(i.json)).filter(s => s !== null);
let mejorScore = scores.length > 0 ? Math.max(...scores) : null;

// Si no hay chunks -> no hay información.
// Si hay chunks pero el mejor score es numérico y está por debajo del
// umbral -> tampoco hay información suficiente.
// Si no se pudo extraer score (formato distinto), se confía en que haya
// al menos un chunk devuelto por Pinecone.
const tieneInformacion =
  chunksEncontrados > 0 && (mejorScore === null || mejorScore >= UMBRAL_SIMILITUD);

const contexto = items.map(i => extraerTexto(i.json)).filter(Boolean).join('\n\n---\n\n');

// Se recuperan el mensaje original y el sessionId directamente del
// nodo del chat trigger para no depender de que viajen por la cadena.
const chatInput = $('Chat cliente').item.json.chatInput;
const sessionId = $('Chat cliente').item.json.sessionId;

return [{
  json: {
    tieneInformacion,
    chunksEncontrados,
    mejorScore,
    umbral: UMBRAL_SIMILITUD,
    contexto,
    chatInput,
    sessionId
  }
}];
